,cash,kind,note.text);await DB.i.set('price',price.toString());if(x.mounted)Navigator.pop(x);msg(c,'تم تسجيل البيع والفاتورة');}catch(e){msg(x,e.toString().replaceAll('Exception: ',''));}},child:const Text('حفظ البيع'))])));}
